    html = TPL.format(**{k: v for k, v in c.items() if k not in ("bars", "trades")},
                      bars=json.dumps(c["bars"]), trades=json.dumps(c["trades"]))
    with open(os.path.join(HERE, fn), "w", encoding="utf-8") as f:
        f.write(html)
    print("wrote", fn)
